options.script:
name = crisis.7100.a
begin_event_chain = {
			event_chain = cosmogenesis_chain
			target = root
		}
add_event_chain_counter = {
			event_chain = "cosmogenesis_chain"
			counter = "cosmogenesis_level_reached"
			amount = 1
		}
custom_tooltip = new_cosmogenesis_tech_tt

script:
country_event = { # Taking the AP - Start level 1
	id = crisis.7100
	title = "crisis.7100.name"
	desc = crisis.7100.desc
	picture = GFX_evt_cosmogenesis_crisis
	show_sound = event_death_cult
	is_triggered_only = yes
	event_chain = cosmogenesis_chain

	option = {
		name = crisis.7100.a
		begin_event_chain = {
			event_chain = cosmogenesis_chain
			target = root
		}
		add_event_chain_counter = {
			event_chain = "cosmogenesis_chain"
			counter = "cosmogenesis_level_reached"
			amount = 1
		}
		custom_tooltip = new_cosmogenesis_tech_tt
	}
}

country_event = { # Reaching Level 2
	id = crisis.7105
	title = "crisis.7105.name"
	desc = crisis.7105.desc
	picture = GFX_evt_synaptic_lathe
	show_sound = event_death_cult
	event_chain = cosmogenesis_chain

	is_triggered_only = yes

	immediate = {
		add_event_chain_counter = {
			event_chain = "cosmogenesis_chain"
			counter = "cosmogenesis_level_reached"
			amount = 1
		}
	}

	option = {
		name = crisis.7105.a
		custom_tooltip = new_cosmogenesis_tech_tt
	}
}

country_event = { # Reaching Level 3
	id = crisis.7110
	title = "crisis.7110.name"
	desc = crisis.7110.desc
	picture = GFX_evt_black_hole
	show_sound = event_death_cult
	event_chain = cosmogenesis_chain

	is_triggered_only = yes

	immediate = {
		add_event_chain_counter = {
			event_chain = "cosmogenesis_chain"
			counter = "cosmogenesis_level_reached"
			amount = 1
		}
	}

	option = {
		name = crisis.7110.a
		custom_tooltip = new_cosmogenesis_tech_tt
	}

	after = {
		hidden_effect = {
			random_country = {
				limit = {
					OR = {
						is_country_type = fallen_empire
						is_country_type = awakened_fallen_empire
					}
					is_fanatic_materialist = yes
				}
				save_event_target_as = materialist_fe
			}
			country_event = { id = crisis.7111 days = 7 }
		}
	}
}

options.script:
name = fallen_empires_awakening.2.b
event_target:materialist_fe = {
			add_opinion_modifier = {
				modifier = opinion_cosmogenesis_thesis
				who = root
			}
		}

name = crisis.7111.b
add_modifier = {
			modifier = cosmogenesis_sorry
			days = 1800
		}

trigger:
is_triggered_only = yes
fire_only_once = yes
trigger = {
		exists = event_target:materialist_fe
	}

script:
country_event = {
	id = crisis.7111
	title = TRANSMISSION
	desc = crisis.7111.desc

	picture_event_data = {
		portrait = event_target:materialist_fe
		planet_background = event_target:materialist_fe
		graphical_culture = event_target:materialist_fe
		city_level = event_target:materialist_fe
		room = event_target:materialist_fe
	}

	diplomatic = yes
	is_triggered_only = yes
	fire_only_once = yes

	trigger = {
		exists = event_target:materialist_fe
	}

	option = {
		name = fallen_empires_awakening.2.b
		event_target:materialist_fe = {
			add_opinion_modifier = {
				modifier = opinion_cosmogenesis_thesis
				who = root
			}
		}
	}

	option = {
		name = crisis.7111.b
		add_modifier = {
			modifier = cosmogenesis_sorry
			days = 1800
		}
	}
}

