	id = crisis.7120
	title = "crisis.7120.name"
	desc = crisis.7120.desc
	picture = GFX_evt_cosmogenesis_crisis
	show_sound = event_death_cult
	event_chain = cosmogenesis_chain

	is_triggered_only = yes

	immediate = {
		add_event_chain_counter = {
			event_chain = "cosmogenesis_chain"
			counter = "cosmogenesis_level_reached"
			amount = 1
		}
	}

	option = {
		name = crisis.7120.a
		custom_tooltip = new_cosmogenesis_tech_tt
	}

	after = {
		# TOTAL WAR TIME
		every_country = {
			limit = {
				is_country_type = fallen_empire
				NOT = {
					is_at_war_with = root
				}
			}
			declare_war = {
				target = root
				name = cosmogenesis_materialist_war
				attacker_war_goal = wg_end_threat
			}
		}
	}
}

