	id = crisis.7225
	title = "crisis.7225.name"
	desc = crisis.7225.desc
	picture = GFX_evt_warm_barren
	show_sound = event_worrying_signal

	is_triggered_only = yes

	option = {
		trigger = {
			is_nomadic = no
		}
		name = crisis.7225.a
		every_owned_planet = {
			limit = {
				solar_system.star = {
					NOT = { is_star_class = sc_black_hole }
				}
			}
			add_modifier = {
				modifier = cosmogenesis_superlight_planet_2
				days = 330
			}
			add_planet_devastation = 50
		}
		random_owned_planet = {
			limit = {
				is_dry = yes
			}
			weights = {
				base = 1
				modifier = {
					factor = 0.1
					is_capital = yes
				}
			}
			change_pc = pc_barren
			hidden_effect = {
				destroy_colony = yes
				add_modifier = {
					modifier = terraforming_candidate
					days = -1
				}
			}
		}
		random_owned_planet = {
			limit = {
				is_dry = no
				is_artificial = no
			}
			change_pc = pc_desert
		}
		if = {
			limit = {
				NOT = {
					root = {
						is_same_value = FROMFROMFROM
					}
				}
				has_communications = FROMFROMFROM
			}
			add_opinion_modifier = {
				modifier = opinion_cosmogenesis_thesis
				who = FROMFROMFROM
			}
		}
		else_if = {
			limit = {
				is_same_value = FROMFROMFROM
			}
			custom_tooltip = cosmogenesis_negative_opinion_tt
		}
		hidden_effect = {
			every_planet_within_border = {
				limit = {
					solar_system.star = {
						NOT = { is_star_class = sc_black_hole }
					}
					OR = {
						is_pre_ftl_colony_type = yes
						AND = {
							NOT = { exists = owner }
							is_a_habitable_planet_megastructure = yes
						}
					}
				}
				add_modifier = {
					modifier = cosmogenesis_superlight_planet_2
					days = 360
				}
			}
		}
	}

	option = {
		trigger = {
			is_nomadic = yes
		}
		name = crisis.7225.b
		every_owned_colony = {
			limit = {
				solar_system.star = {
					NOT = { is_star_class = sc_black_hole }
				}
			}
			add_modifier = {
				modifier = cosmogenesis_superlight_planet_2
				days = 330
			}
			add_planet_devastation = 50
		}
		if = {
			limit = {
				NOT = {
					root = {
						is_same_value = FROMFROMFROM
					}
				}
				has_communications = FROMFROMFROM
			}
			add_opinion_modifier = {
				modifier = opinion_cosmogenesis_thesis
				who = FROMFROMFROM
			}
		}
		else_if = {
			limit = {
				is_same_value = FROMFROMFROM
			}
			custom_tooltip = cosmogenesis_negative_opinion_tt
		}
	}

	after = {
		hidden_effect = {
			country_event = { id = crisis.7230 days = 331 }
		}
	}
}

