event = {
	id = crisis.8043
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		# Checking if she appeared, we're after speech 1...
		has_global_flag = synth_queen_happened
		has_global_flag = synth_queen_speech_1_happened
		NOT = { has_global_flag = synth_queen_speech_2_happened }
		any_country = {
			is_country_type = synth_queen
		}
		# ...and she killed all Fallen Empires
		NOT = {
			any_country = {
				OR = {
					is_country_type = fallen_empire
					is_country_type = awakened_fallen_empire
				}
			}
		}
	}

	immediate = {
		set_global_flag = synth_queen_speech_2_happened
		event_target:synth_queen_country_global = {
			# Start the Doomclock
			if = {
				limit = {
					NOT = {
						any_situation = {
							is_situation_type = situation_synth_queen_doomclock
						}
					}
				}
				start_situation = {
					type = situation_synth_queen_doomclock
					effect = {
						save_global_event_target_as = synth_queen_doomclock_situation
					}
				}
			}
			# Ensure the Fallen Empire ships are dead dead
			every_system_within_border = {
				limit = {
					exists = starbase
					starbase = {
						fleet = {
							NOR = {
								is_ship_size = starbase_synth_queen
								is_ship_size = big_starbase_synth_queen
							}
						}
					}
				}
				starbase = {
					fleet = {
						delete_fleet = this
					}
				}
			}
		}

		every_playable_country = {
			if = {
				limit = {
					is_ai = no
				}
				# if it's not an AI empire, play the conversation
				country_event = { id = crisis.8045 }
			}
			else = {
				# if not, set up things manually
				country_event = { id = crisis.8044 }
			}
		}
	}

	after = {
		#SQ recalls fleets, shores them up, then sends them on patrols
		event_target:synth_queen_country_global = {
			random_system_within_border = {
				limit = {
					has_star_flag = synth_queen_capital
				}
				random_system_planet = {
					limit = {
						has_carrier_flag = synth_queen_bastille
					}
					save_global_event_target_as = synth_queen_capital
				}
			}

			every_owned_fleet = {
				limit = {
					is_mobile = yes
				}
				auto_move_to_planet = {
					target = event_target:synth_queen_capital
					clear_auto_move_on_arrival = yes
				}
			}
		}
	}
}

