country_event = {
	id = crisis.8044
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		has_country_flag = speech_1
		NOR = {
			has_country_flag = speech_2
			has_country_flag = synth_queen_conversation_ongoing
		}
		any_country = {
			is_country_type = synth_queen
		}
		NOT = {
			any_country = {
				OR = {
					is_country_type = fallen_empire
					is_country_type = awakened_fallen_empire
				}
			}
		}
	}


	immediate = {
		set_country_flag = speech_2
		synth_queen_give_storm_project = yes
		# Give some default opinion
		event_target:synth_queen_country_global = {
			add_trust = {
				amount = 5
				who = root.owner
			}
		}
		# Start the Situation
		set_country_flag = synth_queen_situation_started
		start_situation = {
			type = situation_synth_queen_player_facing
			target = this
		}
		if = {
			limit = {
				has_country_flag = synth_queen_researched_first_storm_project
			}
			synth_queen_progress_situation = { SCORE = 1 }
		}
		# Create the outposts
		if = {
			limit = {
				any_system_within_border = {
					is_bottleneck_system = no
					has_any_megastructure = no
					NOT = {
						any_system_planet = {
							OR = {
								is_colonizable = yes
								is_colony = yes
							}
						}
					}
				}
			}
			technological_gifts_of_the_synth_queen_effect = yes
			random_system_within_border = {
				limit = {
					is_bottleneck_system = no
					has_any_megastructure = no
					NOT = {
						any_system_planet = {
							OR = {
								is_colonizable = yes
								is_colony = yes
							}
						}
					}
				}
				synth_queen_wipe_system = yes
				synth_queen_create_outpost = yes
			}
		}
		# If not, pick a different system
		else = {
			capital_scope = {
				closest_system = {
					min_steps = 1
					use_bypasses = no
					limit = {
						is_bottleneck_system = no
						has_any_megastructure = no
						NOT = {
							any_system_planet = {
								OR = {
									is_colonizable = yes
									is_colony = yes
								}
							}
						}
					}
					set_star_flag = synth_queen_player_system
					synth_queen_wipe_system = yes
					synth_queen_create_outpost = yes
				}
			}
		}
	}
}

