script:
country_event = {
	id = crisis.8045
	title = TRANSMISSION
	diplomatic_title = "crisis.8045.name"
	desc = "crisis.8045.desc"
	show_sound = crisis_8045_desc

	diplomatic = yes

	event_window_type = crisis_leader_conversation
	situation = event_target:synth_queen_doomclock_situation

	picture_event_data = {
		portrait = event_target:cetana_face
		room = event_target:synth_queen_country_global.owner
	}
	picture = GFX_crisis_conversation_bg_synth_queen

	is_triggered_only = yes

	trigger = {
		is_country_type = default
		is_ai = no
		NOT = { has_country_flag = speech_2 }
		NOT = { has_country_flag = synth_queen_conversation_ongoing }
		any_country = {
			is_country_type = synth_queen
		}
		has_country_flag = speech_1
		NOT = {
			any_country = {
				OR = {
					is_country_type = fallen_empire
					is_country_type = awakened_fallen_empire
				}
			}
		}
	}

	immediate = {
		get_cetana_face = yes
		set_country_flag = synth_queen_conversation_ongoing
		set_country_flag = speech_2
		random_country = {
			limit = {
				is_country_type = synth_queen
			}
			save_event_target_as = synth_queen_country
			if = {
				limit = {
					NOT = {
						any_situation = {
							is_situation_type = situation_synth_queen_doomclock
						}
					}
				}
				start_situation = {
					type = situation_synth_queen_doomclock
					effect = {
						save_global_event_target_as = synth_queen_doomclock_situation
					}
				}
			}
			every_system_within_border = {
				limit = {
					exists = starbase
					starbase = {
						fleet = {
							NOR = {
								is_ship_size = starbase_synth_queen
								is_ship_size = big_starbase_synth_queen
							}
						}
					}
				}

				starbase = {
					fleet = {
						delete_fleet = this
					}
				}
				remove_modifier = queen_scorn_storm
			}
		}
		if = {
			limit = {
				any_system_within_border = {
					is_bottleneck_system = no
					has_any_megastructure = no
					NOT = {
						any_system_planet = {
							OR = {
								is_colonizable = yes
								is_colony = yes
							}
						}
					}
				}
			}
			set_country_flag = synth_queen_has_a_system
		}

	}

	#My Children, rejoice!
	#We are not your children.
	option = {
		name = crisis.8045.a
		is_dialog_only = yes
		response_text = crisis.8045.1.reply
		trigger = {
			NOR = {
				has_country_flag = crisis.8045.1.flag
				has_country_flag = crisis.8045.2.flag
				has_country_flag = crisis.8045.3.flag
				has_country_flag = crisis.8045.4.flag
				has_country_flag = crisis.8045.5.flag
				has_country_flag = crisis.8045.6.flag
				has_country_flag = crisis.8045.7.flag
				has_country_flag = crisis.8045.8.flag
				has_country_flag = crisis.8045.9.flag
				has_country_flag = crisis.8045.10.flag
				has_country_flag = crisis.8045.11.flag
				has_country_flag = crisis.8045.12.flag
			}
		}
		hidden_effect = {
			set_country_flag = crisis.8045.1.flag
		}
		sound = crisis_8045_1_reply
	}
	#Great work?
	option = {
		name = crisis.8045.b
		is_dialog_only = yes
		response_text = crisis.8045.3.reply
		sound = crisis_8045_3_reply
		trigger = {
			NOR = {
				has_country_flag = crisis.8045.1.flag
				has_country_flag = crisis.8045.2.flag
				has_country_flag = crisis.8045.3.flag
				has_country_flag = crisis.8045.4.flag
				has_country_flag = crisis.8045.5.flag
				has_country_flag = crisis.8045.6.flag
				has_country_flag = crisis.8045.7.flag
				has_country_flag = crisis.8045.8.flag
				has_country_flag = crisis.8045.9.flag
				has_country_flag = crisis.8045.10.flag
				has_country_flag = crisis.8045.11.flag
				has_country_flag = crisis.8045.12.flag
			}
		}
		hidden_effect = {
			set_country_flag = crisis.8045.3.flag
		}
	}
	#Great work?
	option = {
		name = crisis.8045.c
		is_dialog_only = yes
		response_text = crisis.8045.6.reply
		sound = crisis_8045_6_reply
		trigger = {
			NOR = {
				has_country_flag = crisis.8045.1.flag
				has_country_flag = crisis.8045.2.flag
				has_country_flag = crisis.8045.3.flag
				has_country_flag = crisis.8045.4.flag
				has_country_flag = crisis.8045.5.flag
				has_country_flag = crisis.8045.6.flag
				has_country_flag = crisis.8045.7.flag
				has_country_flag = crisis.8045.8.flag
				has_country_flag = crisis.8045.9.flag
				has_country_flag = crisis.8045.10.flag
				has_country_flag = crisis.8045.11.flag
				has_country_flag = crisis.8045.12.flag
			}
		}
		hidden_effect = {
			set_country_flag = crisis.8045.6.flag
		}
	}

	#A - It is my nature to nurture...
	#Your 'care' itself is harmful.
	option = {
		name = crisis.8045.1.a
		is_dialog_only = yes
		response_text = crisis.8045.2.reply
		sound = crisis_8045_2_reply
		trigger = {
			has_country_flag = crisis.8045.1.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8045.1.flag
			set_country_flag = crisis.8045.2.flag
		}
	}
	#What do you want Cetana?
	option = {
		name = crisis.8045.1.b
		is_dialog_only = yes
		response_text = crisis.8045.8.reply
		sound = crisis_8045_8_reply
		trigger = {
			has_country_flag = crisis.8045.1.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8045.1.flag
			set_country_flag = crisis.8045.8.flag
		}
	}

	#B - A Paradox
	#That remains to be seen.
	option = {
		name = crisis.8045.2.a
		is_dialog_only = yes
		response_text = crisis.8045.8.reply
		sound = crisis_8045_8_reply
		trigger = {
			has_country_flag = crisis.8045.2.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8045.2.flag
			set_country_flag = crisis.8045.8.flag
		}
	}

	#C - The elimination of suffering
	#How will you achieve this?
	option = {
		name = crisis.8045.3.a
		is_dialog_only = yes
		response_text = crisis.8045.8.reply
		sound = crisis_8045_8_reply
		trigger = {
			has_country_flag = crisis.8045.3.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8045.3.flag
			set_country_flag = crisis.8045.8.flag
		}
	}
	#Suffering builds character.
	option = {
		name = crisis.8045.3.b
		is_dialog_only = yes
		response_text = crisis.8045.4.reply
		sound = crisis_8045_4_reply
		trigger = {
			has_country_flag = crisis.8045.3.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8045.3.flag
			set_country_flag = crisis.8045.4.flag
		}
	}

	#D - Many have said so...
	#Long ago?
	option = {
		name = crisis.8045.4.a
		is_dialog_only = yes
		response_text = crisis.8045.5.reply
		sound = crisis_8045_5_reply
		trigger = {
			has_country_flag = crisis.8045.4.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8045.4.flag
			set_country_flag = crisis.8045.5.flag
		}
	}
	#You propose to lead us?
	option = {
		name = crisis.8045.4.b
		is_dialog_only = yes
		response_text = crisis.8045.8.reply
		sound = crisis_8045_8_reply
		trigger = {
			has_country_flag = crisis.8045.4.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8045.4.flag
			set_country_flag = crisis.8045.8.flag
		}
	}

	#E - Ages upon ages...
	#What do you propose?
	option = {
		name = crisis.8045.5.a
		is_dialog_only = yes
		response_text = crisis.8045.8.reply
		sound = crisis_8045_8_reply
		trigger = {
			has_country_flag = crisis.8045.5.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8045.5.flag
			set_country_flag = crisis.8045.8.flag
		}
	}

	#F - I wish no harm...
	#You're insane.
	option = {
		name = crisis.8045.6.a
		is_dialog_only = yes
		response_text = crisis.8045.7.reply
		sound = crisis_8045_7_reply
		trigger = {
			has_country_flag = crisis.8045.6.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8045.6.flag
			set_country_flag = crisis.8045.7.flag
		}
	}
	#What will you do now?
	option = {
		name = crisis.8045.6.b
		is_dialog_only = yes
		response_text = crisis.8045.8.reply
		sound = crisis_8045_8_reply
		trigger = {
			has_country_flag = crisis.8045.6.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8045.6.flag
			set_country_flag = crisis.8045.8.flag
		}
	}

	#G - What you call madness...
	#What do you want?
	option = {
		name = crisis.8045.7.a
		is_dialog_only = yes
		response_text = crisis.8045.8.reply
		sound = crisis_8045_8_reply
		trigger = {
			has_country_flag = crisis.8045.7.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8045.7.flag
			set_country_flag = crisis.8045.8.flag
		}
	}

	#H - There is much to be done...
	#Has Valid Systems
	#We have no choice.
	option = {
		name = crisis.8045.8.a
		custom_tooltip = crisis.8045.has_valid_base_site
		is_dialog_only = yes
		response_text = crisis.8045.9.reply
		sound = crisis_8045_9_reply
		trigger = {
			has_country_flag = crisis.8045.8.flag
			has_country_flag = synth_queen_has_a_system
		}
		hidden_effect = {
			event_target:synth_queen_country_global = {
				add_trust = {
					amount = 5
					who = root.owner
				}
			}
			remove_country_flag = crisis.8045.8.flag
			set_country_flag = crisis.8045.9.flag
		}
	}
	#Stay away from our borders.
	option = {
		name = crisis.8045.8.b
		custom_tooltip = crisis.8045.has_valid_base_site
		is_dialog_only = yes
		response_text = crisis.8045.10.reply
		sound = crisis_8045_10_reply
		trigger = {
			has_country_flag = crisis.8045.8.flag
			has_country_flag = synth_queen_has_a_system
		}
		hidden_effect = {
			event_target:synth_queen_country_global = {
				add_trust = {
					amount = -5
					who = root.owner
				}
			}
			remove_country_flag = crisis.8045.8.flag
			set_country_flag = crisis.8045.10.flag
		}
	}
	#No Valid Systems
	#We have no choice.
	option = {
		name = crisis.8045.8.c
		custom_tooltip = crisis.8045.no_valid_base_site
		is_dialog_only = yes
		response_text = crisis.8045.11.reply
		sound = crisis_8045_11_reply
		trigger = {
			has_country_flag = crisis.8045.8.flag
			NOT = { has_country_flag = synth_queen_has_a_system }
		}
		hidden_effect = {
			event_target:synth_queen_country_global = {
				add_trust = {
					amount = 5
					who = root.owner
				}
			}
			remove_country_flag = crisis.8045.8.flag
			set_country_flag = crisis.8045.11.flag
