script:
country_event = {
	id = crisis.8060
	title = TRANSMISSION
	diplomatic_title = "crisis.8060.name"
	desc = "crisis.8060.like.desc"
	show_sound = crisis_8060_like_desc
	diplomatic = yes

	event_window_type = crisis_leader_conversation
	situation = event_target:synth_queen_doomclock_situation

	picture_event_data = {
		portrait = event_target:cetana_face
		room = event_target:synth_queen_country_global.owner
	}
	picture = GFX_crisis_conversation_bg_synth_queen

	is_triggered_only = yes

	immediate = {
		get_cetana_face = yes
		random_country = {
			limit = {
				is_country_type = synth_queen
			}
			save_event_target_as = synth_queen_country
		}
	}

	#H - Declare war after finishing the situation
	option = {
		name = crisis.8060.war
		icon = {
			icon = GFX_text_casus_belli_target
			text = WARGOAL
		}
		allow = {
			custom_tooltip = {
				fail_text = "synth_queen_not_able_to_attack_cetana_situation"
				has_country_flag = synth_queen_cannot_yeet_the_fleets
				has_country_flag = protected_from_queen_storm
			}
			custom_tooltip = {
				fail_text = "synth_queen_not_able_to_attack_cetana_storm"
				has_country_flag = synth_queen_researched_first_storm_project
				has_country_flag = protected_from_queen_storm
			}
		}
		trigger = {
			has_synth_queen_dialogue_flag = no
		}
		if = {
			limit = {
				has_country_flag = synth_queen_cannot_yeet_the_fleets
				has_country_flag = protected_from_queen_storm
			}
			custom_tooltip = synth_queen_able_to_attack_cetana
		}
		is_dialog_only = yes
		response_text = crisis.8060.war.reply
		sound = crisis_8060_war_reply

		hidden_effect = {
			set_country_flag = crisis.8060.war.flag
		}
	}

	option = { # Yes
		name = crisis.8060.war.a
		custom_tooltip = crisis.8060.war.a.tt
		trigger = {
			has_country_flag = crisis.8060.war.flag
		}
		is_dialog_only = yes
		response_text = crisis.8060.war.1.reply
		sound = crisis_8060_war_1_reply
		hidden_effect = {
			remove_country_flag = crisis.8060.war.flag
			set_country_flag = crisis.8060.war.1.flag
		}
	}

	option = { # No
		name = crisis.8060.war.b
		trigger = {
			has_country_flag = crisis.8060.war.flag
		}
		is_dialog_only = yes
		response_text = crisis.8060.neutral.reply
		sound = crisis_8060_neutral_reply
		hidden_effect = {
			remove_country_flag = crisis.8060.war.flag
		}
	}

 	# War starts
	option = {
		name = crisis.8060.war.1.a
		trigger = {
			has_country_flag = crisis.8060.war.1.flag
		}
		if = {
			limit = {
				has_modifier = synth_queen_nanite_apprentice
			}
			remove_modifier = synth_queen_nanite_apprentice
		}
		hidden_effect = {
			event_target:synth_queen_country_global = {
				set_country_type = awakened_synth_queen
				set_country_flag = protected_from_queen_storm
				country_event = { id = crisis.8156 days = 7 }
				synth_queen_debuff = yes
			}
			every_country = {
				limit = {
					OR = {
						is_country_type = awakened_synth_queen
						is_country_type = synth_queen_convoys
						is_country_type = synth_queen_outposts
					}
				}
				set_faction_hostility = {
					set_hostile = yes
				}
			}
			set_global_flag = synth_queen_war_started
			remove_country_flag = crisis.8060.war.1.flag
			set_country_flag = synth_queen_cannot_yeet_the_fleets
			set_country_flag = protected_from_queen_storm
		}
		random_situation = {
			limit = {
				is_situation_type = situation_synth_queen_player_facing
			}
			destroy_situation = this
		}
	}

	#A - How can we help?
	option = {
		name = crisis.8060.a
		trigger = {
			has_synth_queen_dialogue_flag = no
		}
		is_dialog_only = yes
		response_text = crisis.8060.a.reply
