country_event = {
	id = crisis.8080
	title = "crisis.8080.name"
	diplomatic_title = "crisis.8080.name"
	desc = "crisis.8080.desc"
	show_sound = crisis_8080_desc

	diplomatic = yes

	event_window_type = crisis_leader_conversation
	situation = event_target:synth_queen_doomclock_situation
	picture_event_data = {
		portrait = event_target:cetana_face
		room = event_target:synth_queen_country_global.owner
	}
	picture = GFX_crisis_conversation_bg_synth_queen

	is_triggered_only = yes

	trigger = {
		NOR = {
			has_global_flag = synth_queen_war_started
			has_country_flag = synth_queen_first_demand
		}
	}

	immediate = {
		get_cetana_face = yes
		set_country_flag = mother_knows_best_small_favor
		random_country = {
			limit = {
				is_country_type = synth_queen
			}
			save_event_target_as = synth_queen_country
			set_country_flag = synth_queen_conversation_ongoing
		}
		#Picks your moon
		if = {
			limit = {
				capital_scope = {
					has_moon = yes
					any_moon = {
						NOR = {
							habitable_planet = yes
							is_planet_class = pc_shattered
							is_planet_class = pc_broken
							is_planet_class = pc_shattered_2
							is_planet_class = pc_habitat
						}
					}
				}
			}
			capital_scope = {
				random_moon = {
					limit = {
						NOR = {
							habitable_planet = yes
							is_planet_class = pc_shattered
							is_planet_class = pc_broken
							is_planet_class = pc_shattered_2
							is_planet_class = pc_habitat
						}
					}
					set_carrier_flag = synth_queen_databank_location@root
					save_event_target_as = synth_queen_databank_location
				}
			}
		}
		#Picks a random useless planet in your system
		else_if = {
			limit = {
				capital_scope = {
					solar_system = {
						any_system_planet = {
							is_star = no
							NOR = {
								habitable_planet = yes
								is_planet_class = pc_shattered
								is_planet_class = pc_broken
								is_planet_class = pc_shattered_2
								is_planet_class = pc_habitat
								is_planet_class = pc_gas_giant
							}
						}
					}
				}
			}
			capital_scope = {
				solar_system = {
					random_system_planet = {
						limit = {
							is_star = no
							NOR = {
								habitable_planet = yes
								is_planet_class = pc_shattered
								is_planet_class = pc_broken
								is_planet_class = pc_shattered_2
								is_planet_class = pc_habitat
								is_planet_class = pc_gas_giant
							}
						}
						set_carrier_flag = synth_queen_databank_location@root
						save_event_target_as = synth_queen_databank_location
					}
				}
			}
		}
	}

	#First Option
	option = {
		name = crisis.8080.a
		trigger = {
			is_machine_empire = no
			NOR = {
				has_country_flag = crisis.8080.1.flag
				has_country_flag = crisis.8080.2.flag
				has_country_flag = crisis.8080.3.flag
				has_country_flag = crisis.8080.4.flag
				has_country_flag = crisis.8080.5.flag
			}
		}
		is_dialog_only = yes
		response_text = crisis.8080.1.reply
		sound = crisis_8080_1_reply
		hidden_effect = {
			set_country_flag = crisis.8080.1.flag
		}
	}

	option = {
		name = crisis.8080.b
		trigger = {
			is_machine_empire = yes
			NOR = {
				has_country_flag = crisis.8080.1.flag
				has_country_flag = crisis.8080.2.flag
				has_country_flag = crisis.8080.3.flag
				has_country_flag = crisis.8080.4.flag
				has_country_flag = crisis.8080.5.flag
			}
		}
		is_dialog_only = yes
		response_text = crisis.8080.1.reply
		sound = crisis_8080_1_reply
		hidden_effect = {
			set_country_flag = crisis.8080.1.flag
		}
	}

	#A1 - What databank?
	option = {
		name = crisis.8080.1.a
		trigger = {
			has_country_flag = crisis.8080.1.flag
		}
		is_dialog_only = yes
		response_text = crisis.8080.2.reply
		sound = crisis_8080_2_reply
		hidden_effect = {
			remove_country_flag = crisis.8080.1.flag
			set_country_flag = crisis.8080.2.flag
		}
	}

	#A2 - Rewarded?
	option = {
		name = crisis.8080.1.b
		trigger = {
			is_megacorp = no
			has_country_flag = crisis.8080.1.flag
		}
		is_dialog_only = yes
		response_text = crisis.8080.3.reply
		sound = crisis_8080_3_reply
		hidden_effect = {
			remove_country_flag = crisis.8080.1.flag
			set_country_flag = crisis.8080.3.flag
		}
	}

	option = {
		name = crisis.8080.1.c
		trigger = {
			is_megacorp = yes
			has_country_flag = crisis.8080.1.flag
		}
		is_dialog_only = yes
		response_text = crisis.8080.3.reply
		sound = crisis_8080_3_reply
		hidden_effect = {
			remove_country_flag = crisis.8080.1.flag
			set_country_flag = crisis.8080.3.flag
		}
	}

	#B1 - Very well.
	option = {
		name = crisis.8080.2.a
		trigger = {
			has_country_flag = crisis.8080.2.flag
		}
		is_dialog_only = yes
		response_text = crisis.8080.4.reply
		sound = crisis_8080_4_reply
		hidden_effect = {
			remove_country_flag = crisis.8080.2.flag
			set_country_flag = crisis.8080.4.flag
		}
	}

	#B2 - We are not your servants.
	option = {
		name = crisis.8080.2.b
		custom_tooltip = synth_queen_disapprove
		trigger = {
			has_country_flag = crisis.8080.2.flag
		}
		is_dialog_only = yes
		response_text = crisis.8080.5.reply
		sound = crisis_8080_5_reply
		hidden_effect = {
			set_country_flag = rebellious_child
			event_target:synth_queen_country = {
				add_trust = {
					amount = -5
					who = root.owner
				}
			}
			remove_country_flag = crisis.8080.2.flag
			set_country_flag = crisis.8080.5.flag
		}
