	#C1 - Very well.
	option = {
		name = crisis.8080.3.a
		trigger = {
			has_country_flag = crisis.8080.3.flag
		}
		is_dialog_only = yes
		response_text = crisis.8080.4.reply
		sound = crisis_8080_4_reply
		hidden_effect = {
			remove_country_flag = crisis.8080.3.flag
			set_country_flag = crisis.8080.4.flag
