	option = {
		name = crisis.8080.3.b
		custom_tooltip = synth_queen_disapprove
		trigger = {
			has_country_flag = crisis.8080.3.flag
		}
		is_dialog_only = yes
		response_text = crisis.8080.5.reply
		sound = crisis_8080_5_reply
		hidden_effect = {
			set_country_flag = rebellious_child
			event_target:synth_queen_country = {
				add_trust = {
					amount = -5
					who = root.owner
				}
			}
			remove_country_flag = crisis.8080.3.flag
			set_country_flag = crisis.8080.5.flag
		}
	}

	#D1 - That remains to be seen.
	option = {
		name = crisis.8080.4.a
		custom_tooltip = crisis.8080.special_project_tooltip
		trigger = {
			has_country_flag = crisis.8080.4.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8080.4.flag
			enable_special_project = {
				name = "THE_SYNTH_QUEENS_DATABANK"
