	option = {
		name = crisis.8095.1.b
		custom_tooltip = synth_queen_approve
		trigger = {
			has_country_flag = crisis.8095.1.flag
		}
		hidden_effect = {
			event_target:synth_queen_country = {
				add_trust = {
					amount = 5
					who = root.owner
				}
			}
			remove_country_flag = crisis.8095.1.flag
			remove_country_flag = synth_queen_conversation_ongoing
		}
	}

	#B1 - Shut her off..
	option = {
		name = crisis.8095.2.a
		custom_tooltip = synth_queen_disapprove
		trigger = {
			has_country_flag = crisis.8095.2.flag
		}
		hidden_effect = {
			remove_country_flag = crisis.8095.2.flag
			event_target:synth_queen_country = {
				add_trust = {
					amount = -5
					who = root.owner
				}
			}
