event = {
	id = crisis.8135
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		has_global_flag = synth_queen_happened
		any_country = {
			is_country_type = synth_queen_outposts
		}
	}

	immediate = {
		random_country = {
			limit = {
				is_country_type = synth_queen
			}

			random_list = {
				40 = {}
				60 = {
					modifier = {
						factor = 3
						count_country = {
							count <= 5
							limit = {
								is_country_type = synth_queen_convoys
							}
						}
					}
					modifier = { #Galaxy size ponderation.
						factor = 0.5
						galaxy_size = tiny
					}
					modifier = {
						factor = 0.75
						galaxy_size = small
					}
					modifier = {
						factor = 1.5
						galaxy_size = large
					}
					modifier = {
						factor = 2
						galaxy_size = huge
					}
					modifier = {
						factor = 0
						OR = {
							AND = {
								count_country = {
									count >= 10
									limit = {
										is_country_type = synth_queen_convoys
									}
								}
								galaxy_size = tiny
							}
							AND = {
								count_country = {
									count >= 15
									limit = {
										is_country_type = synth_queen_convoys
									}
								}
								galaxy_size = small
							}
							AND = {
								count_country = {
									count >= 20
									limit = {
										is_country_type = synth_queen_convoys
									}
								}
								galaxy_size = medium
							}
							AND = {
								count_country = {
									count >= 25
									limit = {
										is_country_type = synth_queen_convoys
									}
								}
								galaxy_size = large
							}
							AND = {
								count_country = {
									count >= 30
									limit = {
										is_country_type = synth_queen_convoys
									}
								}
								galaxy_size = huge
							}
						}
					}

					synth_queen_create_convoy_fleet = yes
				}
			}
		}
	}
}

