script:
country_event = {
	id = crisis.8140
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		is_country_type = synth_queen_convoys
		from.solar_system = {
			OR = {
				has_star_flag = synth_queen_outpost
				has_star_flag = synth_queen_capital
			}
		}
	}

	immediate = {
		if = { #If at capital move to an outpost
			limit = {
				from.solar_system = {
					has_star_flag = synth_queen_capital
				}
			}
			event_target:synth_queen_country_global = {
				random_system = {
					limit = {
						exists = owner
						owner = { is_country_type = synth_queen_outposts }
						has_star_flag = synth_queen_outpost
						NOT = { has_star_flag = incoming_convoy }
					}
					star = {
						save_event_target_as = convoy_destination
					}
					set_timed_star_flag = {
						flag = incoming_convoy
						years = 1
					}
				}
				random_situation = {
					limit = {
						is_situation_type = situation_synth_queen_doomclock
					}
					add_situation_progress = 3
				}
			}
		}
		else = { #Else return to capital
			random_system = {
				limit = {
					exists = owner
					owner = { is_country_type = synth_queen }
					has_star_flag = synth_queen_capital
				}
				star = {
					save_event_target_as = convoy_destination
				}
			}
		}
		from = {
			auto_move_to_planet = {
				target = event_target:convoy_destination
				clear_auto_move_on_arrival = yes
			}
		}
	}
}

