country_event = {
	id = crisis.8156
	hide_window = yes
	is_triggered_only = yes

	fire_only_once = yes

	immediate = {
		# Capital: located
		random_system_within_border = {
			limit = {
				has_star_flag = synth_queen_capital
			}
			star = {
				save_event_target_as = synth_queen_ships_destination
			}
		}

		# Own fleet: patrol mode
		every_owned_fleet = {
			limit = {
				NOT = { has_fleet_flag = synth_queen_titan_ship }
			}
			synth_queen_fleet_patrol = yes
		}

		# Except for the titan. You chill, titan.
		every_owned_fleet = {
			limit = {
				has_fleet_flag = synth_queen_titan_ship
			}
			if = { # If already in Synth Queen territory, stay here
				limit = {
					exists = space_owner
					space_owner = { is_same_value = root }
				}
				synth_queen_fleet_garrison = yes
			}
			else = { # If not, return to the capital, THEN stay there
				remove_auto_move_target = yes
				auto_move_to_planet = {
					target = event_target:synth_queen_ships_destination
					clear_auto_move_on_arrival = yes
					arrival_effect = synth_queen_fleet_garrison
				}
			}
		}

		# Outposts: dismantled
		every_country = {
			limit = {
				is_country_type = synth_queen_outposts
			}
			every_owned_fleet = {
				every_controlled_ship = {
					limit = {
						is_ship_size = big_starbase_synth_queen
					}
					delete_ship = this
				}
				# Ships: ready to go home
				set_fleet_flag = synth_queen_returning_outpost_ship
				set_owner = root
				remove_auto_move_target = yes
				auto_move_to_planet = {
					target = event_target:synth_queen_ships_destination
					clear_auto_move_on_arrival = yes
				}
			}
			destroy_country = yes
		}

		# Convoys: go home
		every_country = {
			limit = {
				is_country_type = synth_queen_convoys
			}
			every_owned_fleet = {
				set_owner = root
				remove_auto_move_target = yes
				auto_move_to_planet = {
					target = event_target:synth_queen_ships_destination
					clear_auto_move_on_arrival = yes
					arrival_effect = synth_queen_fleet_convoys_patrol
				}
			}
			destroy_country = yes
		}
	}

	after = {
		every_playable_country = {
			limit = {
				has_communications = root
			}
			country_event = {
				id = crisis.8158
			}
		}
	}
}

