options.script:
name = INTRIGUING
owner = {
			if = {
				# if for some weird reason you already got an arc site on your capital...
				limit = {
					capital_scope = {
						exists = archaeological_site
					}
				}
				# try spawning it elsewhere
				random_planet_within_border = {
					limit = {
						habitable_planet = yes
						is_colony = yes
						is_capital = no
						NOT = { exists = archaeological_site }
					}
					save_event_target_as = history_planet
				}
				if = {
					limit = {
						exists = event_target:history_planet
					}
					event_target:history_planet = {
						create_archaeological_site = synth_queen_history_site_2
					}
					owner = {
						set_country_flag = synth_queen_history_site_2_arcsite_owner_@event_target:history_planet
					}
				} # if no valid planets, spawn it where you found it
				else = {
					fromfrom = {
						create_archaeological_site = synth_queen_history_site_2
					}
					owner = {
						set_country_flag = synth_queen_history_site_2_arcsite_owner_@fromfrom
					}
				}
			}
			# Spawn arc site on the capital by default for non nomads
			else_if = {
				limit = {
					is_nomadic = no
				}
				capital_scope = {
					create_archaeological_site = synth_queen_history_site_2
				}
				owner = {
					set_country_flag = synth_queen_history_site_2_arcsite_owner_@capital_scope.planet
				}
			}
			else = {
				capital_scope = {
					solar_system = {
						random_system_planet = {
							limit = {
								NOT = { is_planet_class = pc_ark }
							}
							create_archaeological_site = synth_queen_history_site_2
							root.owner? = {
								set_country_flag = synth_queen_history_site_2_arcsite_owner_@prev
							}
						}
					}
				}
			}
			synth_queen_progress_situation = { SCORE = 1 }
		}

