				}
				every_ship_in_system = {
					limit = {
						is_ship_size = synth_queen_titan
					}
					fleet = {
						set_owner = root
					}
					set_disabled = no
				}
			}
			every_galaxy_planet = {
				limit = {
					has_carrier_flag = synth_queen_bastille
				}
				change_pc = pc_shattered
				clear_deposits = yes
				clear_planet_modifiers = yes
			}
			random_country = {
				limit = {
					is_country_type = awakened_synth_queen
				}
				every_owned_fleet = {
					delete_fleet = this
				}
				every_owned_leader = {
					kill_leader = {
						show_notification = no
					}
				}
			}
			stop_crisis_sound = yes
			end_crisis = yes
			remove_global_flag = galactic_crisis_recently_fired
			if = {
				limit = {
					has_global_flag = galactic_crisis_early_defeat_tracker_1
				}
				remove_global_flag = galactic_crisis_early_defeat_tracker_1
				multiply_crisis_strength = 1.5
			}
			else_if = {
				limit = {
					has_global_flag = galactic_crisis_early_defeat_tracker_2
				}
				remove_global_flag = galactic_crisis_early_defeat_tracker_2
				multiply_crisis_strength = 1.25
			}
			from = { set_country_flag = with_great_power_achievement }
			remove_global_flag = synth_queen_ongoing
			set_global_flag = synth_queen_defeated
			country_event = { id = crisis.23020 }
		}
	}
}

